class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        int n = nums.size();
        long long maxPrefix = max(nums[0], nums[1]);
        long long maxDiff = (long long)nums[0] - nums[1];
        long long ans = 0;
        for (int k = 2; k < n; k++) {
            ans = max(ans, maxDiff * (long long)nums[k]);
            maxDiff = max(maxDiff, maxPrefix - nums[k]);
            maxPrefix = max(maxPrefix, (long long)nums[k]);
        }
        return ans;
    }
};
